// Extraer alertas activas de Prometheus o generar fallback para pruebas controladas
let firingAlerts = [];
try {
  const data = $input.first().json;
  const groups = (data.data && data.data.groups) || [];
  for (const g of groups) {
    for (const r of (g.rules || [])) {
      if (r.alerts && r.alerts.length > 0) {
        for (const a of r.alerts) {
          if (a.state === 'firing') {
            firingAlerts.push({
              alertname: a.labels.alertname || 'AlertaGeneral',
              instance: a.labels.instance || a.labels.job || 'infraestructura',
              severity: a.labels.severity || 'warning',
              summary: a.annotations.summary || a.annotations.message || 'Sin resumen',
              description: a.annotations.description || 'Sin detalle disponible',
              activeAt: a.activeAt || new Date().toISOString()
            });
          }
        }
      }
    }
  }
} catch (e) {
  // Ignorar error y usar fallback
}

let incident;
let isSimulation = false;

if (firingAlerts.length > 0) {
  incident = firingAlerts[0];
} else {
  // Simulación realista para pruebas en la defensa oral
  isSimulation = true;
  incident = {
    alertname: "PostgresPrimaryDown",
    instance: "gymbro-db-node1:5432",
    severity: "critical",
    summary: "Nodo primario de PostgreSQL/Patroni caído",
    description: "El contenedor gymbro-db-node1 no responde a los probes de etcd/Patroni. HAProxy ha desconectado el tráfico de escritura en el puerto 5000.",
    activeAt: new Date().toISOString()
  };
}

const prompt = `Se ha producido un incidente crítico en la infraestructura de SmartGymBro:
- Alerta: ${incident.alertname}
- Instancia / Servicio: ${incident.instance}
- Severidad: ${incident.severity}
- Resumen: ${incident.summary}
- Descripción: ${incident.description}
- Modo: ${isSimulation ? 'SIMULACIÓN CONTROLADA (DEMO)' : 'INCIDENTE REAL EN VIVO'}

Consulta el playbook vectorial de procedimientos estándar (SOP) y genera:
1. DIAGNÓSTICO: Causa raíz probable y afectación en la arquitectura.
2. COMANDOS DE MITIGACIÓN INMEDIATA: Comandos exactos de consola (Docker, Patroni, HAProxy).
3. PROCEDIMIENTO DE VERIFICACIÓN: Comprobación de salud post-incidente.
4. RECOMENDACIÓN DE CIBERSEGURIDAD Y ALTA DISPONIBILIDAD.`;

return [{
  json: {
    alertname: incident.alertname,
    instance: incident.instance,
    severity: incident.severity,
    summary: incident.summary,
    description: incident.description,
    timestamp: incident.activeAt,
    isSimulation: isSimulation,
    prompt: prompt
  }
}];

// Base de Conocimiento Vectorial / SOP de Procedimientos Operativos SmartGymBro
const playbookDB = [
  {
    topic: "PostgresPrimaryDown / Fallo en Base de Datos / Patroni",
    keywords: ["postgres", "patroni", "db", "database", "node1", "node2", "node3", "5432", "5000"],
    diagnostico: "Caída del nodo primario o desconexión del cluster HA Patroni-PostgreSQL. El quórum etcd promueve un réplica a líder mediante failover automático.",
    comandos: [
      "# 1. Verificar estado del cluster Patroni:",
      "docker exec -it gymbro-db-node2 patronictl -c /etc/patroni/patroni.yml list",
      "# 2. Si el contenedor primario fue detenido o crasheó, reiniciarlo:",
      "docker start gymbro-db-node1",
      "# 3. En caso de desincronización del nodo, forzar re-inicialización:",
      "docker exec -it gymbro-db-node2 patronictl -c /etc/patroni/patroni.yml reinit gymbro-cluster gymbro-db-node1",
      "# 4. Verificar balanceador HAProxy en puertos 5000 (Primary) y 5001 (Replicas):",
      "curl -s http://localhost:7000"
    ],
    verificacion: "Ejecutar patronictl topology y validar que el nodo esté en estado 'running' y sincronizado con etcd.",
    ciberseguridad: "Garantiza RPO < 1s y RTO < 30s. Previene split-brain gracias al consenso etcd en cluster impar."
  },
  {
    topic: "GymbroBackendDown / Fallo en API Node.js Express",
    keywords: ["backend", "express", "3100", "api", "node"],
    diagnostico: "La API Node.js Express de SmartGymBro no responde a las solicitudes HTTP o el proceso se detuvo por excepción no capturada.",
    comandos: [
      "# 1. Consultar últimas 100 líneas de logs:",
      "docker logs --tail 100 gymbro-backend",
      "# 2. Reiniciar el contenedor:",
      "docker restart gymbro-backend",
      "# 3. Validar probe de salud:",
      "curl -I http://localhost:3100/health"
    ],
    verificacion: "Confirmar HTTP 200 en endpoint /health y retorno de métricas en /metrics para Prometheus.",
    ciberseguridad: "Evitar exposición de stack trace en producción mediante NODE_ENV=production y rate-limiting en Nginx."
  },
  {
    topic: "HAProxyDown / Fallo en Enrutador de Base de Datos",
    keywords: ["haproxy", "proxy", "5000", "5001", "7000"],
    diagnostico: "HAProxy caído o estadísticas inaccesibles. La aplicación no puede resolver el nodo primario de escritura.",
    comandos: [
      "# 1. Reiniciar proxy:",
      "docker restart gymbro-haproxy",
      "# 2. Validar panel web:",
      "curl -u admin:adminpass http://localhost:7000"
    ],
    verificacion: "Comprobar que los backends gymbro-db-node1, node2 y node3 aparezcan en verde.",
    ciberseguridad: "Credenciales de estadísticas protegidas con HTTP Basic Auth."
  }
];

const queryLower = (query || "").toLowerCase();
let bestMatch = playbookDB[0]; // fallback default
for (const item of playbookDB) {
  for (const kw of item.keywords) {
    if (queryLower.includes(kw)) {
      bestMatch = item;
      break;
    }
  }
}

return JSON.stringify({
  sop_encontrado: bestMatch.topic,
  diagnostico_recomendado: bestMatch.diagnostico,
  comandos_mitigacion: bestMatch.comandos.join('\n'),
  procedimiento_verificacion: bestMatch.verificacion,
  impacto_ciberseguridad: bestMatch.ciberseguridad
}, null, 2);

const alertname = $('Extraer Incidente y Contexto').first().json.alertname;
const instance = $('Extraer Incidente y Contexto').first().json.instance;
const output = $('Agente IA – Análisis y Playbook').first().json.output;
const emailSent = $('Enviar Correo con Sugerencia IA').first().json;

console.log('[WF-DEFENSA] Ejecución exitosa para alerta:', alertname, 'en', instance);

return [{
  json: {
    status: 'SUCCESS',
    workflow: 'WF-DEFENSA',
    alertname: alertname,
    instance: instance,
    ai_playbook_length: (output || '').length,
    email_result: emailSent,
    timestamp: new Date().toISOString()
  }
}];
